// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.unifiedimport timber.log.Timberimport android.content.Contextimport android.content.Intentimport android.net.Uriimport com.roshan.persona.connectivity.model.MessagingAppimport com.roshan.persona.connectivity.model.ShareContentimport com.roshan.persona.connectivity.model.ShareTargetimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Share Engine (Module 11 v3 — Step 11.7). * * NOUS-enhanced sharing — decides the best share target based on content. * * ## How it works * *  - Photo → "Share to WhatsApp?" (if WhatsApp installed) *  - URL → "Share to browser?" or "Share to Rohit via SMS?" *  - Text → "Share to clipboard?" or "Share to Notes?" * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§ShareEngine</a> */class ShareEngine(    private val context: Context,    private val dispatcher: CoroutineDispatcher,) {    /**     * Get recommended share targets for [content].     *     * @param content the content to share.     * @return ranked list of share targets (best first).     */    suspend fun getShareTargets(content: ShareContent): List<ShareTarget> = withContext(dispatcher) {        val targets = mutableListOf<ShareTarget>()        // WhatsApp (if installed).        if (isAppInstalled("com.whatsapp")) {            targets.add(ShareTarget(                appName = "WhatsApp",                packageName = "com.whatsapp",                isRecommended = content.imageUri != null, // WhatsApp is great for photos                reason = if (content.imageUri != null) "Best for photos" else null,            ))        }        // Telegram (if installed).        if (isAppInstalled("org.telegram.messenger")) {            targets.add(ShareTarget(                appName = "Telegram",                packageName = "org.telegram.messenger",                isRecommended = false,            ))        }        // SMS (always available).        targets.add(ShareTarget(            appName = "SMS",            packageName = "com.android.messaging",            isRecommended = content.text != null && content.text.length < 160,            reason = if (content.text != null && content.text.length < 160) "Short text — good for SMS" else null,        ))        // Clipboard (for text).        if (content.text != null) {            targets.add(ShareTarget(                appName = "Clipboard",                packageName = "com.roshan.persona.clipboard",                isRecommended = false,            ))        }        targets    }    /**     * Share [content] to [target].     *     * @return true if the share intent was launched.     */    suspend fun share(content: ShareContent, target: ShareTarget): Boolean = withContext(dispatcher) {        val intent = Intent(Intent.ACTION_SEND).apply {            type = content.mimeType            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)            content.text?.let { putExtra(Intent.EXTRA_TEXT, it) }            content.imageUri?.let { putExtra(Intent.EXTRA_STREAM, Uri.parse(it)) }            content.fileUri?.let { putExtra(Intent.EXTRA_STREAM, Uri.parse(it)) }            if (target.packageName != "com.roshan.persona.clipboard") {                setPackage(target.packageName)            }        }        try {            if (target.packageName == "com.roshan.persona.clipboard") {                // Copy to clipboard.                val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as? android.content.ClipboardManager                    ?: run {                        Timber.tag(TAG).e("ClipboardManager unavailable")                        return@withContext false                    }                val clip = android.content.ClipData.newPlainText("NOUS Share", content.text ?: "")                clipboard.setPrimaryClip(clip)                Timber.tag(TAG).i("Copied to clipboard.")            } else {                context.startActivity(Intent.createChooser(intent, "Share via").apply {                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)                })            }            true        } catch (t: Throwable) {            Timber.tag(TAG).e("Share failed", t)            false        }    }    private fun isAppInstalled(packageName: String): Boolean = try {        context.packageManager.getPackageInfo(packageName, 0)        true    } catch (t: Throwable) {        false    }    private companion object {        private const val TAG = "ShareEngine"    }}// ═══════════════════════════════════════════════════════════════════════════/** * NOUS — Live Translation Bridge (Module 11 v3 — Step 11.7, Elite Feature). * * Pipes active call audio to Module 5 (Voice) for real-time translation. * * ## How it works (per strategy v3 §"Real-Time Call Translation") * * ``` * User is on a call with someone speaking Hindi → user speaks English *   ↓ * LiveTranslationBridge: *   1. Captures incoming call audio (from CallRecordingEngine's AudioRecorder) *   2. Module 5 STT transcribes in real-time *   3. Translates to user's language (via Module 4 LLM or translation API) *   4. Displays translation on screen OR whispers via earpiece * ``` * * ## v1 approach * * For v1, the bridge is an interface + orchestrator — the actual audio * capture + STT + translation wiring happens in Step 11.8 (Facade) when * all modules are connected. The bridge defines the contract. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§Real-Time Call Translation</a> */class LiveTranslationBridge(    private val translationService: TranslationService?,    private val displayCallback: (String) -> Unit,    private val dispatcher: CoroutineDispatcher,) {    private var isActive = false    /**     * Start live translation for the current call.     *     * @param sourceLanguage the caller's language ("hi").     * @param targetLanguage the user's language ("en").     */    fun start(sourceLanguage: String, targetLanguage: String) {        if (translationService == null) {            Timber.tag(TAG).w("Translation service not available — cannot start live translation.")            return        }        isActive = true        Timber.tag(TAG).i("Live translation started: $sourceLanguage → $targetLanguage.")    }    /**     * Process a chunk of call audio for translation.     *     * Called by CallRecordingEngine's AudioRecorder when new audio is available.     *     * @param audioChunk raw PCM audio data.     */    suspend fun processAudioChunk(audioChunk: ByteArray) = withContext(dispatcher) {        if (!isActive || translationService == null) return@withContext        // 1. Transcribe audio → text (Module 5 STT).        val transcription = translationService.transcribe(audioChunk)        if (transcription.isNullOrBlank()) return@withContext        // 2. Translate text.        val translated = translationService.translate(transcription)        if (translated.isNullOrBlank()) return@withContext        // 3. Display translation.        displayCallback(translated)    }    /** Stop live translation. */    fun stop() {        isActive = false        Timber.tag(TAG).i("Live translation stopped.")    }    /** True if live translation is active. */    fun isLive(): Boolean = isActive    private companion object {        private const val TAG = "LiveTranslation"    }}/** * Translation service interface — combines STT + translation. * * Real implementation wires Module 5 (STT) + Module 4 (LLM translation). * Tests inject a fake. */interface TranslationService {    /** Transcribe audio to text. */    suspend fun transcribe(audioData: ByteArray): String?    /** Translate text from source to target language. */    suspend fun translate(text: String): String?}